class CallbackDeduplicator:
    """记录已处理的回调流水号及其结果。"""

    def __init__(self):
        self._results = {}

    def record(self, callback_id, result):
        """记录回调的处理结果。"""
        self._results[callback_id] = result

    def result_for(self, callback_id):
        """返回该回调的处理结果。"""
        return self._results.get(callback_id)
